import PasswordContext from "./password-context";
import React, { useState, useEffect } from "react";

const PasswordProvider = (props) => {
  const [items, setItem] = useState([]);
  //  const totalQuantity = items.reduce((acc, item) => acc + item.amount, 0);

  const [showForm, setShowForm] = useState(false);
  const [openProduct, setOpenProduct] = useState(false);
  const [totalQuantity, setTotalQuantity] = useState(0);
  const [title, setTitle] = useState(""); // State variable for title
  const [password, setPassword] = useState(""); // State variable for password

  useEffect(() => {
    setTotalQuantity(items.length);
  }, [items]);

  console.log(totalQuantity);

  const handleForm = () => {
    setShowForm(true);
  };

  const closeForm = () => {
    setShowForm(false);
  };

  const handleProduct = () => {
    setOpenProduct(true);
  };

  const itemHandler = (item) => {
    console.log(item);
    setItem((prevItem) => [...prevItem, item]);
  };

  const deleteItem = (id) => {
    const updatedItems = items.filter((item) => item.id !== id);
    setItem(updatedItems);
  };

   const editItems = (id) => {
    const itemToEdit = items.find((item) => item.id === id);
    if (itemToEdit) {
      setTitle(itemToEdit.title); // Update the title state
      setPassword(itemToEdit.password); // Update the password state
    }
    handleForm(); // Open the modal to edit the item
   };

  const passwordContext = {
    item: items,
    showForm,
    addItem: itemHandler,
    totalQuantity,
    openProduct,
    handleForm,
    closeForm,
    handleProduct,
    removeItem: deleteItem,
    editItem: editItems,
     setTitle,
     set
  };

  return (
    <PasswordContext.Provider value={passwordContext}>
      {props.children}
    </PasswordContext.Provider>
  );
};
export default PasswordProvider;
